def readings():
    result = {}
    for row in READINGS_TEXT.strip().splitlines():
        ref, words, sa, en = row.split("|")
        assert ref not in result, ref
        result[ref] = {"words": words.split(), "meaning_sa": sa, "meaning_en": en}
    return result
